using System;

namespace PlayerViewer.Effects.Sim
{
    /// <summary>
    /// The unit direction tables the equally divided sphere shapes emit along, as the runtime
    /// holds them: eight tables of 2 to 32 points for one shape, 63 tables of 2 to 64 points
    /// for the other.
    /// </summary>
    static class SphereTables
    {
        /// <summary>The point counts of the eight small tables, by the shape's table index.</summary>
        public static readonly int[] SmallCounts = { 2, 3, 4, 6, 8, 12, 20, 32 };

        static readonly float[][] _small = Split(Decode(Small), SmallCounts);
        static readonly float[][] _large = Split(Decode(Large), Range(2, 63));

        /// <summary>Table <paramref name="index"/> of the small set, xyz per point.</summary>
        public static float[] GetSmall(int index) => _small[Math.Clamp(index, 0, 7)];

        /// <summary>The table of <paramref name="count"/> points, 2 to 64, xyz per point.</summary>
        public static float[] GetLarge(int count) => _large[Math.Clamp(count, 2, 64) - 2];

        static float[] Decode(string base64)
        {
            byte[] bytes = Convert.FromBase64String(base64);
            var f = new float[bytes.Length / 4];
            Buffer.BlockCopy(bytes, 0, f, 0, bytes.Length);
            return f;
        }

        static int[] Range(int start, int count)
        {
            var r = new int[count];
            for (int i = 0; i < count; i++)
                r[i] = start + i;
            return r;
        }

        static float[][] Split(float[] all, int[] counts)
        {
            var r = new float[counts.Length][];
            int at = 0;
            for (int i = 0; i < counts.Length; i++)
            {
                r[i] = all[at..(at + counts[i] * 3)];
                at += counts[i] * 3;
            }
            return r;
        }

